CREATE TABLE public.follow_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requester_id uuid NOT NULL, target_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(requester_id,target_id), CHECK(requester_id<>target_id));
GRANT SELECT,INSERT,DELETE ON public.follow_requests TO authenticated; GRANT ALL ON public.follow_requests TO service_role;
ALTER TABLE public.follow_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY requests_read ON public.follow_requests FOR SELECT TO authenticated USING(auth.uid() IN (requester_id,target_id));
CREATE POLICY requests_create ON public.follow_requests FOR INSERT TO authenticated WITH CHECK(auth.uid()=requester_id AND NOT public.is_suspended(auth.uid()));
CREATE POLICY requests_remove ON public.follow_requests FOR DELETE TO authenticated USING(auth.uid() IN (requester_id,target_id));
CREATE OR REPLACE FUNCTION public.can_view_social_profile(_host uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM profiles p WHERE p.id=_host AND (p.is_public OR p.id=auth.uid() OR EXISTS(SELECT 1 FROM profile_follows f WHERE f.follower_id=auth.uid() AND f.following_id=p.id))) $$;
CREATE OR REPLACE FUNCTION public.can_view_recording(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM voice_recordings r WHERE r.id=_id AND (r.host_id=auth.uid() OR public.is_admin(auth.uid()) OR (r.is_public AND public.can_view_social_profile(r.host_id)))) $$;
ALTER POLICY "Public or owned recordings are viewable" ON public.voice_recordings USING(public.can_view_recording(id));
CREATE POLICY published_recording_audio ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='voice-recordings' AND EXISTS(SELECT 1 FROM public.voice_recordings r WHERE public.can_view_recording(r.id) AND (split_part(split_part(r.audio_url,'/voice-recordings/',2),'?',1)=name)));
CREATE OR REPLACE FUNCTION public.guard_social_follow() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.follower_id=NEW.following_id THEN RAISE EXCEPTION 'Cannot follow yourself'; END IF; IF NOT EXISTS(SELECT 1 FROM profiles WHERE id=NEW.following_id AND is_public) AND auth.uid() IS DISTINCT FROM NEW.following_id THEN RAISE EXCEPTION 'Follow request required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_social_follow BEFORE INSERT ON public.profile_follows FOR EACH ROW EXECUTE FUNCTION public.guard_social_follow();
CREATE OR REPLACE FUNCTION public.respond_follow_request(_request uuid,_accept boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r follow_requests; BEGIN SELECT * INTO r FROM follow_requests WHERE id=_request AND target_id=auth.uid() FOR UPDATE; IF r.id IS NULL THEN RAISE EXCEPTION 'Request unavailable'; END IF; IF _accept THEN INSERT INTO profile_follows(follower_id,following_id) VALUES(r.requester_id,r.target_id) ON CONFLICT DO NOTHING; END IF; DELETE FROM follow_requests WHERE id=r.id; END $$;
REVOKE ALL ON FUNCTION public.respond_follow_request(uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.respond_follow_request(uuid,boolean) TO authenticated;
CREATE TABLE public.recording_interactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recording_id uuid NOT NULL REFERENCES public.voice_recordings(id) ON DELETE CASCADE, user_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('like','comment','repost')), body text, created_at timestamptz NOT NULL DEFAULT now(), CHECK(kind<>'comment' OR (length(trim(body)) BETWEEN 1 AND 1000)));
GRANT SELECT ON public.recording_interactions TO anon; GRANT SELECT,INSERT,DELETE ON public.recording_interactions TO authenticated; GRANT ALL ON public.recording_interactions TO service_role;
ALTER TABLE public.recording_interactions ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX recording_reactions_unique ON public.recording_interactions(recording_id,user_id,kind) WHERE kind IN ('like','repost');
CREATE POLICY interactions_read ON public.recording_interactions FOR SELECT TO anon,authenticated USING(public.can_view_recording(recording_id));
CREATE POLICY interactions_insert ON public.recording_interactions FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.can_view_recording(recording_id) AND NOT public.is_suspended(auth.uid()));
CREATE POLICY interactions_delete ON public.recording_interactions FOR DELETE TO authenticated USING(user_id=auth.uid() OR EXISTS(SELECT 1 FROM voice_recordings WHERE id=recording_id AND host_id=auth.uid()));
CREATE TABLE public.social_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recipient_id uuid NOT NULL, actor_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('follow','request','like','comment','repost')), recording_id uuid REFERENCES public.voice_recordings(id) ON DELETE CASCADE, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE,DELETE ON public.social_notifications TO authenticated; GRANT ALL ON public.social_notifications TO service_role;
ALTER TABLE public.social_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY activity_read ON public.social_notifications FOR SELECT TO authenticated USING(recipient_id=auth.uid());
CREATE POLICY activity_update ON public.social_notifications FOR UPDATE TO authenticated USING(recipient_id=auth.uid()) WITH CHECK(recipient_id=auth.uid());
CREATE POLICY activity_delete ON public.social_notifications FOR DELETE TO authenticated USING(recipient_id=auth.uid());
GRANT UPDATE(read_at) ON public.social_notifications TO authenticated; REVOKE UPDATE ON public.social_notifications FROM authenticated; GRANT UPDATE(read_at) ON public.social_notifications TO authenticated;
CREATE OR REPLACE FUNCTION public.social_identity(_ids uuid[]) RETURNS TABLE(id uuid,username text,display_name text,avatar_url text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.username,p.display_name,p.avatar_url FROM profiles p WHERE p.id=ANY(_ids) LIMIT 200 $$;
CREATE OR REPLACE FUNCTION public.social_profile(_username text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('id',p.id,'username',p.username,'display_name',p.display_name,'avatar_url',p.avatar_url,'bio',CASE WHEN public.can_view_social_profile(p.id) THEN p.bio ELSE NULL END,'is_public',p.is_public,'can_view',public.can_view_social_profile(p.id),'followers',(SELECT count(*) FROM profile_follows WHERE following_id=p.id),'following',(SELECT count(*) FROM profile_follows WHERE follower_id=p.id),'recordings',(SELECT count(*) FROM voice_recordings r WHERE r.host_id=p.id AND (r.is_public OR p.id=auth.uid())),'badge',(SELECT badge FROM voice_user_badges WHERE user_id=p.id)) FROM profiles p WHERE lower(p.username)=lower(_username) OR p.id::text=_username LIMIT 1 $$;
CREATE OR REPLACE FUNCTION public.social_follow_list(_user uuid,_kind text) RETURNS TABLE(id uuid,username text,display_name text,avatar_url text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.username,p.display_name,p.avatar_url FROM profile_follows f JOIN profiles p ON p.id=CASE WHEN _kind='followers' THEN f.follower_id ELSE f.following_id END WHERE public.can_view_social_profile(_user) AND CASE WHEN _kind='followers' THEN f.following_id ELSE f.follower_id END=_user ORDER BY f.created_at DESC LIMIT 200 $$;
CREATE OR REPLACE FUNCTION public.emit_social_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE recipient uuid; actor uuid; event text; recording uuid; actor_name text; actor_username text; prefs jsonb; push_id uuid; phrase text; phrase_ar text; BEGIN
IF TG_TABLE_NAME='profile_follows' THEN recipient:=NEW.following_id; actor:=NEW.follower_id; event:='follow';
ELSIF TG_TABLE_NAME='follow_requests' THEN recipient:=NEW.target_id; actor:=NEW.requester_id; event:='request';
ELSE SELECT host_id INTO recipient FROM voice_recordings WHERE id=NEW.recording_id; actor:=NEW.user_id; event:=NEW.kind; recording:=NEW.recording_id; END IF;
IF recipient=actor THEN RETURN NEW; END IF;
INSERT INTO social_notifications(recipient_id,actor_id,kind,recording_id) VALUES(recipient,actor,event,recording);
SELECT notification_preferences INTO prefs FROM profiles WHERE id=recipient;
IF coalesce((prefs->>'social')::boolean,true)=false OR coalesce((prefs->>('social_'||event))::boolean,true)=false THEN RETURN NEW; END IF;
SELECT coalesce(nullif(display_name,''),username,'Someone'),username INTO actor_name,actor_username FROM profiles WHERE id=actor;
phrase:=CASE event WHEN 'follow' THEN ' followed you' WHEN 'request' THEN ' requested to follow you' WHEN 'like' THEN ' liked your recording' WHEN 'comment' THEN ' commented on your recording' ELSE ' reposted your recording' END;
phrase_ar:=CASE event WHEN 'follow' THEN ' بدأ متابعتك' WHEN 'request' THEN ' طلب متابعتك' WHEN 'like' THEN ' أعجب بتسجيلك' WHEN 'comment' THEN ' علّق على تسجيلك' ELSE ' أعاد نشر تسجيلك' END;
INSERT INTO push_broadcasts(kind,title_en,body_en,title_ar,body_ar,path,audience_type,audience_user_id,created_by) VALUES('custom',left(actor_name||phrase,120),'Open MA Scores to view your activity.',left(actor_name||phrase_ar,120),'افتح MaScores لعرض الإشعارات.','/notifications','user',recipient,actor) RETURNING id INTO push_id;
PERFORM net.http_post(url:='https://ontmfbptthwipfzlywwh.supabase.co/functions/v1/send-match-alert',body:=jsonb_build_object('broadcastId',push_id),headers:='{"Content-Type":"application/json"}'::jsonb);
RETURN NEW; END $$;
CREATE TRIGGER follow_activity AFTER INSERT ON public.profile_follows FOR EACH ROW EXECUTE FUNCTION public.emit_social_activity();
CREATE TRIGGER request_activity AFTER INSERT ON public.follow_requests FOR EACH ROW EXECUTE FUNCTION public.emit_social_activity();
CREATE TRIGGER recording_activity AFTER INSERT ON public.recording_interactions FOR EACH ROW EXECUTE FUNCTION public.emit_social_activity();
ALTER PUBLICATION supabase_realtime ADD TABLE public.social_notifications,public.follow_requests,public.recording_interactions;
CREATE OR REPLACE FUNCTION public.social_public_requests() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.is_public AND NOT OLD.is_public THEN INSERT INTO profile_follows(follower_id,following_id) SELECT requester_id,target_id FROM follow_requests WHERE target_id=NEW.id ON CONFLICT DO NOTHING; DELETE FROM follow_requests WHERE target_id=NEW.id; END IF; RETURN NEW; END $$;
CREATE TRIGGER social_public_requests AFTER UPDATE OF is_public ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.social_public_requests();